import { useCallback, useState } from "react";
import uniq from "lodash/uniq";

import useAppStore from "@/store/AppStore";
import { useToast } from "@/ui/use-toast";
import useFilteredRulesList from "@/api/automations/useFilteredRulesList";
import { getCompareExperimentsList } from "@/api/datasets/useCompareExperimentsList";
import { COMPARE_EXPERIMENTS_MAX_PAGE_SIZE } from "@/constants/experiments";
import {
  Experiment,
  ExperimentItem,
  ExperimentsCompare,
} from "@/types/datasets";

type UseEvaluateExperimentTracesParams = {
  experiment: Experiment;
};

const useEvaluateExperimentTraces = ({
  experiment,
}: UseEvaluateExperimentTracesParams) => {
  const workspaceName = useAppStore((state) => state.activeWorkspaceName);
  const { toast } = useToast();

  const projectId = experiment.project_id ?? "";

  const [open, setOpen] = useState(false);
  const [traceIds, setTraceIds] = useState<string[]>([]);
  const [isFetching, setIsFetching] = useState(false);

  const { rules, isLoading: isRulesLoading } = useFilteredRulesList({
    projectId,
    entityType: "trace",
    enabled: Boolean(projectId),
  });

  const handleClick = useCallback(async () => {
    if (!experiment.dataset_id) return;
    setIsFetching(true);
    try {
      const data: { content?: ExperimentsCompare[] } =
        await getCompareExperimentsList(
          {},
          {
            workspaceName,
            datasetId: experiment.dataset_id,
            experimentsIds: [experiment.id],
            truncate: true,
            page: 1,
            size: COMPARE_EXPERIMENTS_MAX_PAGE_SIZE,
          },
        );
      const ids = uniq(
        (data?.content ?? [])
          .flatMap((row) => row.experiment_items ?? [])
          .map((item: ExperimentItem) => item.trace_id)
          .filter((id): id is string => Boolean(id)),
      );

      if (!ids.length) {
        toast({
          title: "Nothing to evaluate",
          description: "No traces are associated with this experiment.",
          variant: "destructive",
        });
        return;
      }

      setTraceIds(ids);
      setOpen(true);
    } catch {
      toast({
        title: "Error",
        description: "Failed to load experiment traces for evaluation.",
        variant: "destructive",
      });
    } finally {
      setIsFetching(false);
    }
  }, [experiment.dataset_id, experiment.id, workspaceName, toast]);

  return {
    projectId,
    open,
    setOpen,
    traceIds,
    isFetching,
    rules,
    isRulesLoading,
    handleClick,
  };
};

export default useEvaluateExperimentTraces;

package com.comet.opik.api.resources.v1.events.tools;

import dev.langchain4j.agent.tool.ToolSpecification;
import dev.langchain4j.model.chat.request.json.JsonObjectSchema;
import jakarta.inject.Singleton;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import reactor.core.publisher.Mono;

@Singleton
@Slf4j
public class GetTraceSpansTool implements ToolExecutor {

    public static final String NAME = "get_trace_spans";

    private static final ToolSpecification SPEC = ToolSpecification.builder()
            .name(NAME)
            .description("Retrieve a high-level overview of all sub-spans (tool calls, LLM calls, "
                    + "guardrails, intermediate steps) for the trace being evaluated. Returns span names, "
                    + "types, truncated input/output, and hierarchy. Use this first to understand the "
                    + "trace structure before drilling into specific spans.")
            .parameters(JsonObjectSchema.builder().build())
            .build();

    @Override
    public String name() {
        return NAME;
    }

    @Override
    public ToolSpecification spec() {
        return SPEC;
    }

    @Override
    public Mono<String> execute(String arguments, @NonNull TraceToolContext ctx) {
        // fromCallable so any throw from SpanTreeSerializer is captured as a Mono error
        // and reported via ToolRegistry's onErrorResume — matches the legacy throw path.
        return Mono.fromCallable(() -> {
            if (!ctx.hasActiveTrace()) {
                // Thread-scoped evaluations have no single active trace. Redirect the model
                // to the per-trace ReadTool path rather than NPEing on ctx.getTrace().
                log.debug("get_trace_spans called with no active trace (thread-scoped evaluation)");
                return ToolArgs.errorJson("get_trace_spans is only available for single-trace"
                        + " evaluations. This is a thread-scoped evaluation — pick a trace from the"
                        + " thread skeleton and call read(type=trace, id=<uuid>) to inspect its"
                        + " spans instead.");
            }
            log.debug("get_trace_spans tool call with arguments: '{}' for trace={}", arguments,
                    ctx.getTrace().id());
            String result = SpanTreeSerializer.serializeOverview(ctx.getSpans());
            log.debug("get_trace_spans summary: traceId='{}', spanCount='{}', outputBytes='{}'",
                    ctx.getTrace().id(), ctx.getSpans().size(), result.length());
            return result;
        });
    }
}
